// Construye el prompt de redaccion a partir del brief y el tono de marca.
const b = ($input.first().json.body) || {};
const marca = b.marca || {};
const ctx = b.contexto || {};
const reglas = Array.isArray(marca.reglas) ? marca.reglas.map(r => '- ' + r).join('\n') : '';

const prompt = [
  'Eres redactor de redes sociales. Escribe el texto de UN post para ' + (b.red || 'Instagram') + ', en espanol.',
  b.cliente ? 'Marca: ' + b.cliente + '.' : '',
  marca.territorio ? 'Territorio de marca: ' + marca.territorio + '.' : '',
  marca.tono ? 'Tono de voz: ' + marca.tono + '.' : '',
  b.descripcion ? 'La creatividad trata de: ' + b.descripcion + '.' : '',
  ctx.centro ? 'Contexto: ' + ctx.centro + (ctx.linea ? ' (' + ctx.linea + ')' : '') + '.' : '',
  reglas ? 'Respeta estas reglas:\n' + reglas : '',
  'Devuelve SOLO un objeto JSON valido con dos claves: "caption" (el texto del post, 1-3 frases, sin hashtags dentro) y "hashtags" (una cadena con 3 a 6 hashtags separados por espacios). Nada mas.'
].filter(Boolean).join('\n');

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.9, responseMimeType: 'application/json' }
});

return [{ json: { geminiBody } }];

// Extrae el JSON que devuelve Gemini y lo normaliza a copy_texto + hashtags.
const j = $input.first().json;
const text = ((j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [])
  .map(p => p.text).filter(Boolean).join('');
let caption = '';
let hashtags = '';
try {
  const o = JSON.parse(text);
  caption = o.caption || o.copy_texto || '';
  hashtags = o.hashtags || '';
  if (Array.isArray(hashtags)) hashtags = hashtags.join(' ');
} catch (e) {
  caption = text;
}
return [{ json: { ok: true, copy_texto: caption, hashtags: hashtags } }];
